import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第五百三十四章 如何进入涅槃的境界？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/534第五百三十四章 如何进入涅槃的境界.md","filePath":"meditation/巴利文大藏经/534第五百三十四章 如何进入涅槃的境界.md"}'),o={name:"meditation/巴利文大藏经/534第五百三十四章 如何进入涅槃的境界.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第五百三十四章-如何进入涅槃的境界" tabindex="-1">第五百三十四章 如何进入涅槃的境界？ <a class="header-anchor" href="#第五百三十四章-如何进入涅槃的境界" aria-label="Permalink to &quot;第五百三十四章 如何进入涅槃的境界？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部41相应6经/迦摩浮经第二(质多相应/处篇/弟子记说)</p><p>有个时候，迦摩浮尊者住在摩叉止陀山的安婆陀伽林中，有一天，质多居士来到迦摩浮尊者的住处，他顶礼迦摩浮尊者后，就在一旁坐下，质多居士对迦摩浮尊者说：“迦摩浮尊者，有几种行为呢？”</p><p>迦摩浮尊者回答：“质多居士，有三种行为：身体行为，言语行为，内心行为。”</p><p>质多居士说：“迦摩浮尊者，您能具体给我讲解一下身体行为，言语行为，内心行为吗？您能给我详细的解释一下这三种行为的法义吗？”</p><p>迦摩浮尊者说：“质多居士，吸气和呼气是身体行为，呼吸是身体行为，集中注意力、观察是言语行为，念想、思想、见解、感受是内心行为。”</p><p>质多居士说：“迦摩浮尊者，为什么呼吸是身体行为？为什么集中注意力、观察是言语行为？为什么念想、思想、见解、感受是内心行为？”</p><p>迦摩浮尊者说：“质多居士，吸气、呼气、呼吸的行为是由身体发起、生起的，吸气、呼气、呼吸的行为是受到身体的支配和限制的，所以呼吸是身体行为。</p><p>质多居士，要先集中注意力、观察，才会说出言语，因此集中注意力、观察是言语行为。</p><p>念想、思想、见解、感受是由内心生起、发起的，念想、思想、见解、感受是受到内心支配和限制的，因此，念想、思想、见解、感受是内心行为。”</p><p>质多居士说：“迦摩浮尊者，如何熄灭、停止一切的念想、思想、见解、感受，进入想受灭的清净境界呢？如何灭尽一切的念想、思想、见解、感受，进入想受灭的清净境界呢？”</p><p>迦摩浮尊者说：“质多居士，当修行人进入想受灭清净境界的时候，他不会想：「我即将进入想受灭境界」，或者不会想：「我正在进入想受灭境界」，或者不会想：「我已经进入想受灭境界」，而是按着一定的修行步骤，一步一步的从初禅境界、二禅境界、三禅境界、四禅境界、空无边处境界、识无边处境界、无所有处境界、非想非非想处境界逐渐进入想受灭境界的（初禅境界、二禅境界、三禅境界、四禅境界、空无边处境界、识无边处境界、无所有处境界、非想非非想处境界，想受灭境界解释，见第四百九十一章），修行人就是这样沿着由浅入深的禅定轨迹，引导进入想受灭境界的。”</p><p>质多居士说：“迦摩浮尊者，修行人进入想受灭境界的过程中，最先熄灭、灭尽的是什么行为呢？是身体行为、言语行为还是内心行为？”</p><p>迦摩浮尊者说：“质多居士，当修行人进入想受灭境界之前，言语行为第一个被熄灭、灭尽，身体行为第二个被熄灭、灭尽，内心行为最后第三个被熄灭、灭尽。”</p><p>质多居士说：“迦摩浮尊者，我现在有个疑惑，请您为我解答，死去的人与已经进入想受灭境界的修行人有什么不同呢？死去的人与已经进入想受灭境界的修行人有什么差别和区别呢？”</p><p>迦摩浮尊者说：“质多居士，已经死亡的人，他们的身体行为已经熄灭、平息、灭尽，他们的言语行为已经熄灭、平息、灭尽，他们的内心行为已经熄灭、平息、灭尽，他们的寿命已经耗尽，他们的生命已经终结，他们的身体温度已经散失，他们的体温已经下降到与所处环境的温度一样。他们的眼睛、耳朵、鼻子、舌头、身体、内心已经丧失了功能，他们的眼睛、耳朵、鼻子、舌头、身体、内心已经损毁、坏灭。</p><p>质多居士，那些已经进入想受灭境界的修行人，虽然他们的身体行为已经熄灭、平息、灭尽，言语行为已经熄灭、平息、灭尽，内心行为已经熄灭、平息、灭尽，但是，他们的寿命还没有耗尽，他们的生命还没有终结，他们的身体还有温度，他们还有体温，他们的眼睛、耳朵、鼻子、舌头、身体、内心还没有丧失功能，他们的眼睛、耳朵、鼻子、舌头、身体、内心还没有损毁、坏灭。</p><p>质多居士，这就是已经死亡的人与已经进入想受灭境界修行人的不同，这就是已经死亡的人与已经进入想受灭境界修行人的差别和区别。”</p><p>质多居士说：“迦摩浮尊者，那这些已经进入想受灭境界的修行人，他们如何从想受灭境界中出来呢？他们如何从想受灭境界回到现实的世界中来呢？”</p><p>迦摩浮尊者说：“质多居士，当修行人从想受灭清净境界出来的时候，他不会想：「我即将从想受灭境界中出来」，或者不会想：「我正在从想受灭境界中出来」，或者不会想：「我已经从想受灭境界中出来」，而是按着一定的修行步骤，一步一步的从想受灭境界、非想非非想处境界、无所有处境界、识无边处境界、空无边处境界、四禅境界、三禅境界、二禅境界、初禅境界逐渐出来回到现实的世界中（初禅境界、二禅境界、三禅境界、四禅境界、空无边处境界、识无边处境界、无所有处境界、非想非非想处境界，想受灭境界解释，见第四百九十一章），修行人就是这样沿着从深到浅的禅定轨迹，引导回到现实的世界中来的。”</p><p>质多居士说：“迦摩浮尊者，当修行人从想受灭境界中出来的时候，他们第一个生起的是什么呢？他们最先生起的是什么呢？他们最先生起身体行为、言语行为还是内心行为？”</p><p>迦摩浮尊者说：“质多居士，当修行人从想受灭境界中出来的时候，他们最先生起的是内心行为，然后生起身体行为，最后生起言语行为。也就是第一个生起内心行为，第二个生起身体行为，第三个生起言语行为。”</p><p>质多居士说：“迦摩浮尊者，在想受灭境界中的修行人，他们会接触什么呢？他们的触有几种呢？”</p><p>迦摩浮尊者说：“质多居士，在想受灭境界中的修行人，他们有三种触，空触、无相触、无愿触。</p><p>什么是空触呢？就是不执着和挂念眼触、耳触、鼻触、舌触、身触、意触（眼触、耳触、鼻触、舌触、身触、意触解释，见第一百八十九章），相当于眼触、耳触、鼻触、舌触、身触、意触不存在一样，没有一样，没有接触到一样，所以称为空触。”</p><p>什么是无相触？就是不执着和挂念世间的一切事物，不由世间的事物生起贪欲、渴爱。不贪爱、不执着和挂念物质事物、物质身体、声音、气味、味道、触觉、环境变化感觉（冷热、舒适等等）、思想、见解、念想，不贪爱、不执着和挂念世间一切的事物，这就叫着无相触。</p><p>什么是无愿触呢？对于世间的一切都无所求，不贪求世间一切的事物，无愿无求，比如：不求福德功德，不求除灭罪业，不求解脱生死，不求证悟解脱果位。没有任何欲望和要求，无欲无求！也没有任何的愿望希望达成，没有后悔的事情，无愿无悔，这就是无愿触。”</p><p>质多居士说：“迦摩浮尊者，修行人进入想受灭境界的时候，他们会向什么倾斜呢？他们会靠近什么呢？”</p><p>迦摩浮尊者说：“质多居士，进入想受灭境界的修行人，他们会向远离贪欲、渴爱，远离束缚捆绑，远离烦恼和痛苦倾斜，他们会无限接近、靠近没有贪欲、渴爱，没有束缚捆绑，没有烦恼和痛苦的清净境界。”</p><p>质多居士说：“迦摩浮尊者，修行什么方法能够进入想受灭境界呢？”</p><p>迦摩浮尊者说：“质多居士，这个问题实际上您已经问过我了，您问我的第一个问题，其实就是这个问题，我已经给您解答过了，不过我现在可以简要的为您解答：</p><p>止与观这两种修行方法就能让修行人进入想受灭境界。止与观就是进入初禅境界、二禅境界、三禅境界、四禅境界、空无边处境界、识无边处境界、无所有处境界、非想非非想处境界、想受灭的境界的修行方法，也就是先将内心集中专注在单个、纯一不会生起贪欲、渴爱的念想之中，比如将内心集中专注在数呼吸的单一念想上，或者将内心集中专注在眨眼睛的单一念想上，或者将内心集中专注在身体某个部位的感觉单一念想上。以此熄灭各种杂念、妄想，不让内心胡思乱想，不让内心混乱、散乱，让内心先安定、平静、寂静，之后观想正法智慧，比如观想：「世间一切的事物随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有；我的物质身体、感受、念想、行为、认识、分别、判断也是随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的。我的物质身体会生病、衰老、死亡；我的感受、念想、行为、认识、分别、判断会消退、消失。我拥有的物质事物也会破损、衰败、灭亡、消失，我也无法永远的拥有物质事物，我也会失去物质事物。</p><p>我的眼睛、耳朵、鼻子、舌头、身体、内心随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有，我的眼睛、耳朵、鼻子、舌头、身体、内心会丧失功能，会衰败、坏灭。」以此熄灭、灭尽由执着「我」而生起的烦恼和痛苦。</p><p>质多居士，简单的说就是：先熄灭、停止内心中的各种杂念、妄想，不让内心胡思乱想，不让内心混乱、散乱，让内心安宁、平静、寂静下来，先控制住烦恼和痛苦，不让烦恼和痛苦持续不断的生起，这就是止。内心安宁、平静、寂静下来后，再观想各种解脱的智慧，以此熄灭、除灭已经生起来的烦恼和痛苦，这就是观。最终灭尽一切的烦恼和痛苦，证悟解脱的果位，进入没有烦恼，没有痛苦，没有执着，没有挂念，没有念想的涅槃境界。”</p><p>迦摩浮尊者说法后，质多居士虔诚恭敬的顶礼迦摩浮尊者，随喜赞叹迦摩浮尊者说法的无量功德，并按着迦摩浮尊者所说的法去修行。</p>',36)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
